export interface NavigationContext {
  cancelReaderDestinationHold?: () => void;
  epubSeekFrame: number;
  chapterScrollAnchors: { invalidate(): void; remember(): void };
  nextReaderGeneration(kind: string): number;
  returnHistoryKey: string | null;
  folderNavigationTarget: URL | null;
  clearReturnNavigation(): void;
  beginReaderNavigation(): number;
  htmlFrame: HTMLIFrameElement | null;
  viewport: HTMLElement;
  panelState: { open: boolean };
  bookmarkPopover: HTMLElement;
  bookmarkRibbon: HTMLElement;
  readerUiHistoryState: string;
  closeFullSearchView(): void;
  setReaderPanelOpen(open: boolean, focus?: boolean): void;
  turnViewport(direction: number): void;
  readerLifecycle: { disposed: boolean };
  readerAbortController: AbortController;
  documentState: { pageCount: number; restorationReady: boolean };
  isReaderGenerationCurrent(kind: string, generation: number): boolean;
  pdfShellWindow: { ensure(page: number): void; schedule(): void } | null;
  content: HTMLElement;
  pdfShellLayoutReady: Promise<boolean> | null;
  pdfShellsReady: Promise<unknown>;
  capability: { mode?: string | null };
  prioritizePdfManifestPrefetch(url: string | undefined): void;
  pdfPageManifest: { pageUrl(page: number): string } | null;
  renderPdfInBackground(shell: HTMLElement, force: boolean, priority: boolean): Promise<unknown> | undefined;
  readerPageScrollTop(shell: Element): number;
  renderPdfOcrText(shell: HTMLElement): void;
  pageNavigationLockUntil: number;
  cancelSpeculativePdfRenders(shell: HTMLElement): void;
  updateDocumentState(state: { page: number }): void;
  pageInput: HTMLInputElement;
  updateTocCurrentMark(): void;
  updateProgressTools(): void;
  scheduleSave(): void;
  handlePageNavigationFailure(error: unknown, generation: number): void;
  notePdfViewportMotion?: () => void;
  pdfLastScrollTop: number;
  pdfScrollDirection: number;
  scheduleVisiblePdfRenderReconciliation?: (immediate: boolean) => void;
  scheduleMarkerSync(): void;
  saveProgress(): Promise<unknown> | undefined;
  pdfUserHasScrolled: boolean;
  trackReaderResource(cleanup: () => void): unknown;
}
